    <div style="background:#2e1065;padding:20px;border-radius:12px;border:1px solid #4db6ac;margin-bottom:20px;">
    <h3 style="color:#e0f2f1;margin-top:0;">🧠 Lesson Summary</h3>
    <p>Ammonia is prepared by heating an ammonium salt with an alkali, dried with calcium oxide and collected by upward delivery. It is a colourless, pungent, light, very soluble alkaline gas; it forms white fumes with HCl, forms ammonium salts with acids, reduces hot copper(II) oxide and precipitates metal hydroxides. The Haber process (N₂ + 3H₂ ⇌ 2NH₃) uses about 200 atm, about 450 °C and an iron catalyst.</p>
    <h4 style="color:#e0f2f1;margin:16px 0 6px 0;">🗒️ Revision notes</h4>
    <ul style="margin:6px 0;padding-left:22px;">
    <li>Preparation.</li>
    <li>Properties and tests.</li>
    <li>Ammonia as reagent.</li>
    <li>Haber process.</li>
    <li>Calculations.</li>
    </ul>
    </div>
